PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,public_id TEXT UNIQUE NOT NULL,email TEXT UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,avatar_url TEXT,bio TEXT,public_key TEXT NOT NULL,persona TEXT NOT NULL DEFAULT 'general',preferred_lang TEXT NOT NULL DEFAULT 'pl',is_admin INTEGER NOT NULL DEFAULT 0,is_verified INTEGER NOT NULL DEFAULT 0,profile_completed INTEGER NOT NULL DEFAULT 0,failed_logins INTEGER NOT NULL DEFAULT 0,locked_until TEXT,created_at TEXT NOT NULL,last_seen TEXT,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,device_id TEXT NOT NULL,access_hash TEXT UNIQUE NOT NULL,refresh_hash TEXT UNIQUE NOT NULL,access_expires_at TEXT NOT NULL,refresh_expires_at TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT NOT NULL,revoked_at TEXT,replaced_at TEXT);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS recovery_codes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,created_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE IF NOT EXISTS accessibility_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,settings TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contacts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,contact_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,display_name TEXT,verified INTEGER NOT NULL DEFAULT 0,safety_number TEXT,can_receive_alarm INTEGER NOT NULL DEFAULT 0,blocked INTEGER NOT NULL DEFAULT 0,added_at TEXT NOT NULL,UNIQUE(owner_id,contact_user_id));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN('direct','group')),title TEXT,created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_participants(conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'member',joined_at TEXT NOT NULL,left_at TEXT,pinned INTEGER NOT NULL DEFAULT 0,muted INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,last_read_at TEXT,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,ciphertext TEXT NOT NULL,nonce TEXT NOT NULL,media_key TEXT,reply_to_id TEXT REFERENCES messages(id),client_timestamp TEXT NOT NULL,created_at TEXT NOT NULL,edited_at TEXT,deleted_at TEXT,expires_at TEXT,UNIQUE(sender_id,id));
CREATE INDEX IF NOT EXISTS idx_messages_history ON messages(conversation_id,created_at DESC);
CREATE TABLE IF NOT EXISTS message_receipts(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN('delivered','read')),updated_at TEXT NOT NULL,PRIMARY KEY(message_id,user_id));
CREATE TABLE IF NOT EXISTS message_reactions(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,reaction TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(message_id,user_id));
CREATE TABLE IF NOT EXISTS media_objects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,r2_key TEXT UNIQUE NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS emergency_events(id TEXT PRIMARY KEY,initiator_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,location_shared INTEGER NOT NULL DEFAULT 0,latitude REAL,longitude REAL,expires_at TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,cancelled_at TEXT);
CREATE INDEX IF NOT EXISTS idx_emergency_active ON emergency_events(status,expires_at);
CREATE TABLE IF NOT EXISTS provider_configs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL,base_url TEXT,model TEXT,enabled INTEGER NOT NULL DEFAULT 1,is_default INTEGER NOT NULL DEFAULT 0,priority INTEGER NOT NULL DEFAULT 10,usage_count INTEGER NOT NULL DEFAULT 0,notes TEXT,last_used_at TEXT,processing_location TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tiktak_posts(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),caption TEXT NOT NULL,media_key TEXT NOT NULL,media_type TEXT NOT NULL,mood TEXT,is_funny INTEGER NOT NULL DEFAULT 1,captions TEXT,transcript TEXT,image_alt TEXT,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL,deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_tiktak_feed ON tiktak_posts(status,created_at DESC);
CREATE TABLE IF NOT EXISTS communities(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,cover_url TEXT,owner_id TEXT NOT NULL REFERENCES users(id),member_count INTEGER NOT NULL DEFAULT 0,is_private INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS community_members(community_id TEXT NOT NULL REFERENCES communities(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,status TEXT NOT NULL,joined_at TEXT NOT NULL,PRIMARY KEY(community_id,user_id));
CREATE TABLE IF NOT EXISTS community_posts(id TEXT PRIMARY KEY,community_id TEXT NOT NULL REFERENCES communities(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,media_key TEXT,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,parent_id TEXT REFERENCES comments(id),author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_comments_resource ON comments(resource_type,resource_id,created_at);
CREATE TABLE IF NOT EXISTS likes(resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL,PRIMARY KEY(resource_type,resource_id,user_id));
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS music_cache(id TEXT PRIMARY KEY,title TEXT NOT NULL,provider TEXT NOT NULL,prompt TEXT,mood TEXT,r2_key TEXT NOT NULL,duration_ms INTEGER NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,resource_id TEXT,payload TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,device_id TEXT NOT NULL,endpoint TEXT UNIQUE NOT NULL,p256dh TEXT NOT NULL,auth TEXT NOT NULL,platform TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,reason TEXT NOT NULL,details TEXT,status TEXT NOT NULL,reviewer_id TEXT REFERENCES users(id),created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,metadata TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consent_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,scope TEXT,granted_at TEXT NOT NULL,revoked_at TEXT,policy_version TEXT NOT NULL,proof_of_consent TEXT);
